catalog_script_client.script:
function onSubmit() {
    var startDate = g_form.getValue('v_start_date');
    var endDate = g_form.getValue('v_end_date');
    var dosage = g_form.getValue('v_dosage');
    var frequency = g_form.getValue('v_frequency');
    var medicationName = g_form.getValue('v_medication_name');
    var errorMsg = "";

    // Validate dates
    if (!startDate) {
        errorMsg += "Start date is required.\n";
    }
    if (!endDate) {
        errorMsg += "End date is required.\n";
    }
    if (startDate && endDate && new Date(startDate) >= new Date(endDate)) {
        errorMsg += "End date must be after the start date.\n";
    }

    // Validate Dosage: positive numeric value
    var numericDosage = parseFloat(dosage);
    if (!dosage || isNaN(numericDosage) || numericDosage <= 0) {
        errorMsg += "Dosage must be a valid, positive number.\n";
    }

    // Validate frequency
    if (!frequency) {
        errorMsg += "Frequency is required.\n";
    }

    // Validate medication name
    if (!medicationName) {
        errorMsg += "Medication name is required.\n";
    }

    if (errorMsg) {
        alert(errorMsg);
        return false;
    }

    // Prevent double submit flag
    if (window._medication_submit_attempted) {
        window._medication_submit_attempted = false;
        return true; // allow submission
    }

    // Asynchronously check medication existence via GlideAjax
    var ga = new GlideAjax('MedicationAvailability');
    ga.addParam('sysparm_name', 'checkAvailability');
    ga.addParam('sysparm_medication_name', medicationName);

    ga.getXMLAnswer(function(response) {
        if (response === 'Exists') {
            g_form.showFieldMsg('v_medication_name', 
                'Medication "' + medicationName + '" already exists in inventory.', 'error');
            // Do NOT submit form
        } else if (response === 'Not Exists') {
            // Medication does not exist, safe to submit
            window._medication_submit_attempted = true;
            g_form.submit();
        } else {
            alert("Unexpected response from server: " + response);
        }
    });

    // Prevent default submit until async check completes
    return false;
}
